#include <stdio.h>
#include <stddef.h>
#include <libproc.h>
#include <sys/proc_info.h>
#include <sys/proc.h>
int main(void) {
  printf("PROC_PIDTBSDINFO=%d PROC_PIDTBSDINFO_SIZE=%zu sizeof=%zu pid_offset=%zu status_offset=%zu start_sec_offset=%zu start_usec_offset=%zu SZOMB=%d\n",
    PROC_PIDTBSDINFO, (size_t)PROC_PIDTBSDINFO_SIZE, sizeof(struct proc_bsdinfo),
    offsetof(struct proc_bsdinfo, pbi_pid), offsetof(struct proc_bsdinfo, pbi_status),
    offsetof(struct proc_bsdinfo, pbi_start_tvsec), offsetof(struct proc_bsdinfo, pbi_start_tvusec), SZOMB);
  return 0;
}
